async function callAPI(endpointKey, payload, loaderMsg = 'Loading...', suppressLoader = false, timeoutMs = 30000) {
  const ep = ENDPOINTS[endpointKey];
  if (!ep) throw new Error(`Unknown endpoint: ${endpointKey}`);
  // Concurrent-fetch guard: reject duplicate in-flight requests for the same endpoint key
  if (AppState._fetching && AppState._fetching[endpointKey]) {
    const skipMsg = `${ep.name}: duplicate request blocked — already in flight`;
    logTelemetry(ep.name, skipMsg, 'Warning', 0);
    throw new Error(skipMsg);
  }
  if (AppState._fetching) AppState._fetching[endpointKey] = true;
  if (!suppressLoader) showLoader(loaderMsg);
  const start = Date.now();
  // Generate correlation ID for tracing (D-0009)
  const correlationId = (typeof crypto !== 'undefined' && crypto.randomUUID)
    ? crypto.randomUUID()
    : Date.now().toString(36) + Math.random().toString(36).slice(2);
  // AbortController with configurable timeout (D-0010, P1-5)
  const controller = new AbortController();
  const effectiveTimeout = Number(timeoutMs) > 0 ? Number(timeoutMs) : 30000;
  const timeoutId = setTimeout(() => controller.abort(), effectiveTimeout);
  try {
    const resp = await fetch(ep.url, {
      method: ep.method,
      headers: { 'Content-Type': 'application/json', 'X-Correlation-ID': correlationId },
      body: JSON.stringify({ ...payload, correlationId }),
      signal: controller.signal
    });
    clearTimeout(timeoutId);
    const durationMs = Date.now() - start;
    if (!resp.ok) {
      const errText = await resp.text();
      logTelemetry(ep.name, `HTTP ${resp.status}: ${errText.slice(0, 100)} [cid:${correlationId.slice(0,8)}]`, 'Error', durationMs);
      throw new Error(`HTTP ${resp.status}: ${errText.slice(0, 200)}`);
    }
    let data;
    const text = await resp.text();
    try { data = JSON.parse(text); } catch { data = text; }
    logTelemetry(ep.name, `Success • ${typeof data === 'object' ? JSON.stringify(data).length : text.length} bytes [cid:${correlationId.slice(0,8)}]`, 'Success', durationMs);
    setLastUpdated();
    return data;
  } catch(e) {
    clearTimeout(timeoutId);
    const durationMs = Date.now() - start;
    const msg = e.name === 'AbortError' ? `Request timed out after ${Math.round(effectiveTimeout/1000)} seconds` : (e.message || 'Network error');
    logTelemetry(ep.name, `${msg} [cid:${correlationId.slice(0,8)}]`, 'Error', durationMs);
    throw new Error(msg);
  } finally {
    if (AppState._fetching) AppState._fetching[endpointKey] = false;
    if (!suppressLoader) hideLoader();
  }
}

