async function fetchLookups(suppressLoader = false, force = false) {
  // P3-2: Coalesce repeat calls. Reference data (categories, departments,
  // users) only changes when an admin updates the master tables — refetching
  // on every navigation to telemetry / home / sidebar refresh wastes a round
  // trip per visit. Short-circuit unless explicitly forced or data is empty.
  const alreadyLoaded = (AppState.categories?.length > 0)
                     && (AppState.departments?.length > 0);
  if (alreadyLoaded && !force) {
    logTelemetry('Lookups skipped', 'Already cached — pass force=true to refresh', 'Info', 0);
    return;
  }
  try {
    const payload = {
      action: 'lookups',
      operation: 'read',
      mode: 'read',
      source: 'DGO_FAST_Track_WEB_OPS',
      userEmail: AppState.currentUser.email,
      method: 'POST',
      device: { id: 'standalone-html', platform: navigator.platform, ua: navigator.userAgent }
    };
    const raw = await callAPI('E01', payload, 'Loading reference data...', suppressLoader);
    const data = parseResponse(raw);
    // Parse the response structure
    const inner = data && data.data ? data.data : data;
    if (inner && inner.users) AppState.users = inner.users;
    if (inner && inner.categories) AppState.categories = inner.categories;
    if (inner && inner.departments) AppState.departments = inner.departments;
    updateRefDataStats();
    populateLookupDropdowns();
    logTelemetry('Lookups loaded', `Users:${AppState.users.length} Cats:${AppState.categories.length} Depts:${AppState.departments.length}`, 'Success');
  } catch(e) {
    console.error('Lookups error:', e);
    logTelemetry('Lookups', 'Reference data failed to load: ' + e.message, 'Error');
    // Show a user-visible persistent warning so users know dropdowns may be empty
    const warnId = 'lookups-warn-banner';
    if (!document.getElementById(warnId)) {
      const banner = document.createElement('div');
      banner.id = warnId;
      banner.className = 'notify-banner error show';
      banner.style.cssText = 'position:fixed;top:62px;left:50%;transform:translateX(-50%);z-index:9000;min-width:340px;max-width:90vw;box-shadow:var(--shadow-md);';
      banner.innerHTML = '⚠️ Reference data (users, categories, departments) failed to load. Category and assignee dropdowns may be empty. ' +
        '<button class="btn btn-secondary btn-sm" style="margin-left:8px;" onclick="fetchLookups(false, true);this.closest(\'#lookups-warn-banner\').remove()">🔄 Retry</button>' +
        '<button class="btn btn-icon btn-ghost btn-sm" style="margin-left:4px;" onclick="this.closest(\'#lookups-warn-banner\').remove()">✕</button>';
      document.body.appendChild(banner);
      setTimeout(() => { const el = document.getElementById(warnId); if (el) el.remove(); }, 15000);
    }
  }
}

async function fetchDocs(odataFilter = '', suppressLoader = false) {
  // Reset pagination on every fresh fetch
  AppState.docsPage = 0;
  AppState.docsTotalKnown = false;
  try {
    const payload = {
      action: 'getDocs',
      operation: 'read',
      mode: 'read',
      source: 'DGO_FAST_Track_WEB_OPS',
      userEmail: AppState.currentUser.email,
      method: 'POST',
      device: { id: 'standalone-html', platform: navigator.platform, ua: navigator.userAgent },
      odataFilter: odataFilter || null,
      top: AppState.docsPageSize,
      skip: 0
    };
    const raw = await callAPI('E02', payload, 'Fetching documents...', suppressLoader);
    const data = parseResponse(raw);
    // The response is: { ok, status, request, timing, data: { docs: [...] }, errors, meta }
    const inner = data && data.data ? data.data : data;
    const docs = Array.isArray(inner) ? inner : (inner && inner.docs ? inner.docs : []);
    AppState.docs = docs;
    AppState.docsFiltered = [...docs];
    resetDocsFilters(); // STATE-02: reset stale filter state on every fresh fetch
    renderDocsGallery(AppState.docsFiltered);
    updateDocsCount(docs.length);
    updateDocsPaginationUI(docs.length, docs.length < AppState.docsPageSize);
    updateKPIs();
    renderHomeRecentDocs();
    populateDocsStatusFilter();
    updateBulkSelectUI();
    logTelemetry('Docs fetched', `Count: ${docs.length}`, 'Success');
  } catch(e) {
    showGalleryError('docs-gallery', 'Failed to fetch documents: ' + e.message);
  }
}

