async function loadMoreDocs() {
  const nextPage = AppState.docsPage + 1;
  const skip = nextPage * AppState.docsPageSize;
  const btn = document.getElementById('docs-load-more-btn');
  if (btn) { btn.disabled = true; btn.textContent = '⏳ Loading...'; }
  try {
    const payload = {
      action: 'getDocs', operation: 'read', mode: 'read',
      source: 'DGO_FAST_Track_WEB_OPS', userEmail: AppState.currentUser.email,
      method: 'POST', device: { id: 'standalone-html', platform: navigator.platform, ua: navigator.userAgent },
      odataFilter: null, top: AppState.docsPageSize, skip: skip
    };
    const raw = await callAPI('E02', payload, 'Loading more documents...');
    const data = parseResponse(raw);
    const inner = data?.data || data;
    const newDocs = Array.isArray(inner) ? inner : (inner?.docs || []);
    AppState.docsPage = nextPage;
    AppState.docs = [...AppState.docs, ...newDocs];

    const hasActiveDocsFilter = !!(
      (document.getElementById('docs-search')?.value || '').trim() ||
      (document.getElementById('filter-assigned-to')?.value || '') ||
      (document.getElementById('filter-category')?.value || '') ||
      (document.getElementById('filter-status')?.value || '') ||
      (document.getElementById('filter-assignment-status')?.value || '') ||
      (document.getElementById('filter-date-from')?.value || '') ||
      (document.getElementById('filter-date-to')?.value || '')
    );

    if (hasActiveDocsFilter) {
      // Preserve current filters/search after appending
      filterDocs();
    } else {
      AppState.docsFiltered = [...AppState.docs];
      renderDocsGallery(AppState.docsFiltered);
      updateDocsCount(AppState.docs.length);
    }
    updateDocsPaginationUI(newDocs.length, newDocs.length < AppState.docsPageSize);
    updateKPIs();
    updateBulkSelectUI();
    populateDocsStatusFilter();
    logTelemetry('Docs load-more', `New: ${newDocs.length} | Total: ${AppState.docs.length}`, 'Success');
  } catch(e) {
    if (btn) { btn.disabled = false; btn.textContent = '⬇️ Load More Docs'; }
    logTelemetry('Load More Docs', `Failed: ${e.message}`, 'Error');
  }
}

