  const folder = document.getElementById('email-folder-select')?.value || 'inbox';
  const unreadOnly = document.getElementById('unread-only')?.checked || false;
  // Compute next page parameters BEFORE the request; only commit the page increment on success
  const nextPage = AppState.emailsPage + 1;
  const skip = nextPage * AppState.emailsPageSize;
  const btn = document.getElementById('email-load-more-btn');
  if (btn) { btn.disabled = true; btn.textContent = '⏳ Loading...'; }
  try {
    const payload = {
      action: 'emailsfetch',
      operation: 'read',
      mode: 'read',
      source: 'DGO_FAST_Track_WEB_OPS',
      userEmail: AppState.currentUser.email,
