    // Commit page increment only after a successful response
    AppState.emailsPage = nextPage;
    AppState.emails = [...AppState.emails, ...newEmails];
    // Re-apply active search filter after appending to preserve user's current search state
    const activeSearch = (document.getElementById('emails-search')?.value || '').toLowerCase();
    AppState.emailsFiltered = activeSearch
