async function submitEmailTask() {
  const em = AppState.selectedEmail;
  const title = (document.getElementById('etask-title')?.value || '').trim();
  const category = document.getElementById('etask-category')?.value || '';
  const subcategory = document.getElementById('etask-subcategory')?.value || '';
  const assignee = (document.getElementById('etask-assignee')?.value || '').trim();
  const priority = document.getElementById('etask-priority')?.value || 'P3 (Normal)';
  const comments = (document.getElementById('etask-comments')?.value || '').trim();
  const coassignee = (document.getElementById('etask-coassignee')?.value || '').trim();
  const actionReq = document.getElementById('etask-action-req')?.value || '';
  const ccList = [..._etaskCCTags].join(';');

  // Find category record and derive cascading defaults (P2-4: full alignment
  // with the documented CREATE_EMAIL_TASK_ASSIGNMENT_TRIGGER_SCHEMA — mirrors
  // the same default-derivation logic used by selectCategory() on the regular
  // assignment screen, so category-driven fields land in the payload.)
  const catRecord = AppState.categories.find(c => c.Category === category && (!subcategory || c.Subcategory === subcategory));
  const catCode = String(catRecord?.['Category Code'] || '').trim();
  const subCatCode = catRecord ? (catRecord['SubCategory Code'] || '') : '';
  const primaryDSU = catRecord ? (catRecord['Default Primary Responsible'] || '') : '';
  const supportDSU = catRecord ? (catRecord['Default Supporting Department/Unit'] || '') : '';
  const timeline = catRecord ? (catRecord.Timeline || '') : '';
  const dept = AppState.departments.find(d => d.DSU_KEY === primaryDSU);
  const assignedToTitle = dept ? (dept.DSU_HeadTitle || assignee) : assignee;
  const supportDept = supportDSU ? AppState.departments.find(d => d.DSU_KEY === supportDSU) : null;
  const supportAssignedToTitle = supportDept ? (supportDept.DSU_HeadTitle || '') : '';
  const today = new Date().toISOString().split('T')[0];
  const tomorrow = new Date(Date.now() + 86400000).toISOString().split('T')[0];

  // P2-4: Sender is required as an object per the schema; current AppState
  // models it as a flat string from Microsoft Graph normalization. Reconstruct
  // the canonical {name, address} shape, with safe fallbacks.
  const fromAddrObj = (em && (em.fromAddress || em.fromName))
    ? { address: em.fromAddress || em.from?.emailAddress?.address || '', name: em.fromName || em.from?.emailAddress?.name || '' }
    : null;

  // P2-4: Reference ID stub for traceability — server appends the SharePoint
  // task numeric ID. Format mirrors the regular single-assignment flow.
  const refIdStub = `${today.replace(/-/g, '')}-EML-${catCode || 'UNC'}--`;

  const notifyEl = document.getElementById('modal-etask-preview-notify');
  const confirmBtn = document.getElementById('etask-confirm-submit-btn');
  if (confirmBtn) confirmBtn.disabled = true;
  if (notifyEl) { notifyEl.className = 'notify-banner info show'; notifyEl.textContent = '⏳ Submitting task...'; }

  const payload = {
    action: 'emailtotaskassignment',
    operation: 'createTaskFromEmail',
    mode: 'single',
    source: 'DGO_FAST_Track_WEB_OPS',
    userEmail: AppState.currentUser.email,
    method: 'POST',
    device: { id: 'standalone-html', platform: navigator.platform, ua: navigator.userAgent },
    payload: {
      email: {
        id: em?.id || '',
        subject: em?.subject || title,
        receivedDateTime: em?.receivedDateTime || new Date().toISOString(),
        // P2-4: object form per schema (was bare string)
        fromAddress: fromAddrObj,
        webLink: em?.webLink || '',
        conversationId: em?.conversationId || '',
        internetMessageId: em?.internetMessageId || '',
        bodyPreview: em?.bodyPreview || '',
        bodyContent: em?.bodyContent || em?.body?.content || ''
      },
      task: {
        StartDate: today,
        // P2-4: ActivityID is the email message ID for email-sourced tasks
        ActivityID: em?.id || '',
        Title: title,
        Description: em?.bodyPreview || title,
        Status: 'New',
        Category: category,
        CategoryCode: catCode,
        SubCategory: subcategory,
        SubCategoryCode: subCatCode,
        // P2-4: Categorization composite mirrors the bulk-assignment pattern
        Categorization: category && subcategory ? `${category}-${subcategory}` : (category || ''),
        PrimaryDSU: primaryDSU,
        AssignedTo: assignee,
        AssignedToTitle: assignedToTitle,
        AssignedDSU: primaryDSU,
        // P2-4: Support fields populated from cascading category lookup
        supportingAssignedTo: coassignee,
        SupportAssignedTo: coassignee,
        SupportAssignedToTitle: supportAssignedToTitle,
        SupportDSU: supportDSU,
        SupportDSUKey: supportDSU,
        Priority: priority,
        Timeline: timeline,
        // P2-4: Use tomorrow as default acknowledgement/task due (was today,
        // which is unworkable in practice). Server may override.
        AckDue: tomorrow,
        TaskDue: tomorrow,
        AcknowledgementDueBy: tomorrow,
        // Schema explicitly lists this typo'd field name (AcknolwedgementDueBy)
        // — sending both for forward/backward compatibility.
        AcknolwedgementDueBy: tomorrow,
        TaskDueDate: tomorrow,
        CopyTo: ccList,
        ActionRequired: actionReq,
        Comments: comments,
        CreatedBy: AppState.currentUser.email,
        AttachmentLink: em?.webLink || '',
        // P2-4: Pre-reference ID for traceability
        PreReferenceID: refIdStub
      },
      selection: { single: { ID: em?.id || '', RefIDD: '', Title: em?.subject || '' }, items: [] },
      assignment: { type: 'emailtask' }
    }
  };

  try {
    const raw = await callAPI('E05', payload, 'Creating task from email...');
    const data = parseResponse(raw);
    const ref = data?.data?.referenceId || data?.data?.ReferenceID || '';
    if (notifyEl) { notifyEl.className = 'notify-banner success show'; notifyEl.textContent = `✅ Task created successfully!${ref ? ' | Ref: ' + ref : ''}`; }
    logTelemetry('Email Task Created', `Title: ${title} | Assignee: ${assignee}${coassignee ? ' | Co: ' + coassignee : ''}`, 'Success');
    // Clear CC tags
    _etaskCCTags.clear(); renderETaskCCTags();
    setTimeout(() => { closeEmailTaskPreview(); closeEmailToTask(); }, 2000);
  } catch(e) {
    if (confirmBtn) confirmBtn.disabled = false;
    if (notifyEl) { notifyEl.className = 'notify-banner error show'; notifyEl.textContent = `❌ Failed: ${e.message}`; }
    logTelemetry('Email Task', `Failed: ${e.message}`, 'Error');
  }
}

