async function executeBulkAssign() {
  const mode = AppState.bulkConfirmMode;
  const selectedItems = AppState.docs.filter(d => AppState.selectedDocs.has(d.ID));
  const category = document.getElementById('bulk-category').value;
  const subcategory = document.getElementById('bulk-subcategory').value;
  const assignee = document.getElementById('bulk-assignee').value.trim();
  const priority = document.getElementById('bulk-priority').value;
  const comments = document.getElementById('bulk-comments').value.trim();

  document.getElementById('bulk-confirm-proceed-btn').disabled = true;
  closeBulkConfirmModal();

  const catRecord = AppState.categories.find(c => c.Category === category && (!subcategory || c.Subcategory === subcategory));
  const catCode = catRecord ? catRecord['Category Code'] : '';
  const subCatCode = catRecord ? catRecord['SubCategory Code'] : '';
  const primaryDSU = catRecord ? catRecord['Default Primary Responsible'] : '';
  const dept = AppState.departments.find(d => d.DSU_KEY === primaryDSU);
  const assignedToTitle = dept ? dept.DSU_HeadTitle : assignee;
  const today = new Date().toISOString().split('T')[0];
  const tomorrowDate = new Date(); tomorrowDate.setDate(tomorrowDate.getDate() + 1);
  const tomorrow = tomorrowDate.toISOString().split('T')[0];

  const selectedItemsPayload = selectedItems.map(d => ({
    ID: d.ID, RefIDD: String(d.ID), Title: d.Title
  }));

  const payload = {
    action: 'bulkassignment',
    operation: 'create',
    mode: 'bulk',
    source: 'DGO_FAST_Track_WEB_OPS',
    userEmail: AppState.currentUser.email,
    method: 'POST',
    device: { id: 'standalone-html', platform: navigator.platform, ua: navigator.userAgent },
    AssignmentType: 'bulkassignment',
    NewActivityTask: {
      StartDate: today,
      Title: '',
      Status: 'New',
      Category: category,
      CategoryCode: catCode,
      SubCategory: subcategory,
      SubCategoryCode: subCatCode,
      PrimaryDSU: primaryDSU,
      AssignedTo: assignee,
      AssignedToTitle: assignedToTitle,
      AssignedDSU: primaryDSU,
      supportingAssignedTo: '',
      SupportAssignedTo: '',
      SupportDSU: '',
      Priority: priority,
      AcknowledgementDueBy: tomorrow,
      AcknolwedgementDueBy: tomorrow,
      TaskDueDate: tomorrow,
      Comments: comments,
      CreatedBy: AppState.currentUser.email,
      Timeline: 'N/A',
      Categorization: category + '-' + subcategory
    },
    SelectedItems: selectedItemsPayload,
    payload: {
      task: {
        Category: category, CategoryCode: catCode, SubCategory: subcategory, SubCategoryCode: subCatCode,
        PrimaryDSU: primaryDSU, AssignedTo: assignee, AssignedToTitle: assignedToTitle,
        AssignedDSU: primaryDSU, Priority: priority, AcknowledgementDueBy: tomorrow, AcknolwedgementDueBy: tomorrow,
        TaskDueDate: tomorrow, Comments: comments, CreatedBy: AppState.currentUser.email
      },
      selection: { items: selectedItemsPayload },
      assignment: { type: 'bulkassignment' }
    }
  };

  try {
    showNotify('bulk-notify', `⏳ Submitting bulk assignment (${mode})...`, 'info');
    const endpointKey = mode === 'optimized' ? 'E07' : 'E06';
    const raw = await callAPI(endpointKey, payload, `Bulk assigning ${selectedItems.length} items...`, false, 90000);
    const data = parseResponse(raw);
    // Treat any successful HTTP 2xx response (already validated in callAPI) as success
    // Check explicit failure indicators in response body
    const explicitFail = data?.ok === false || data?.ok === 'False' || data?.status === 'error';
    if (!explicitFail) {
      const resultSummary = data?.data?.results
        ? ` | Results: ${data.data.results.filter(r => r.success !== false).length}/${selectedItems.length} succeeded`
        : '';
      showNotify('bulk-notify', `✅ Bulk assignment completed! ${selectedItems.length} items assigned to ${assignee}.${resultSummary}`, 'success');
      logTelemetry('Bulk Assignment', `${selectedItems.length} items → ${assignee} | Mode: ${mode}`, 'Success');
      // Immediately update local AppState for all assigned items so gallery reflects changes without re-fetch
      selectedItems.forEach(item => {
        [AppState.docs, AppState.docsFiltered].forEach(arr => {
          const d = arr.find(x => x.ID === item.ID);
          if (d) {
            d.AssignedTo = assignee;
            d.AssignmentStatus = 'Assigned';
            if (category) d.Category = category;
          }
        });
      });
      updateKPIs();
      AppState.selectedDocs.clear();
      updateBulkSelectUI();
      setTimeout(() => navigateTo('docs'), 2000);
    } else {
      showNotify('bulk-notify', `⚠️ Assignment completed with reported warnings. Check telemetry for details.`, 'warning');
      logTelemetry('Bulk Assignment', `Completed with warnings: ${JSON.stringify(data).slice(0,100)}`, 'Warning');
    }
  } catch(e) {
    showNotify('bulk-notify', `❌ Bulk assign failed: ${e.message}`, 'error');
  }
}

async function submitFlagAction() {
  const action = AppState._pendingFlagAction;
  const doc = AppState.selectedDoc;
  if (!action || !doc) return;
  const flagInfo = FLAG_ACTION_MAP[action];
  const comments = document.getElementById('modal-flag-comments').value.trim();
  const submitBtn = document.getElementById('modal-flag-submit-btn');
  submitBtn.disabled = true;

  const notifyEl = document.getElementById('modal-flag-notify');
  notifyEl.className = 'notify-banner info show';
  notifyEl.textContent = '⏳ Submitting flag action...';

  try {
    // AC6: route through executeSubsidiaryAction dispatcher
    const raw = await executeSubsidiaryAction('flagDocument', doc.ID, doc.Title, {
      operation: 'update',
      mode: 'single',
      FlagAction: {
        DocumentID: doc.ID,
        DocumentTitle: doc.Title,
        FlagType: flagInfo.type,
        FlagLabel: flagInfo.label,
        Comments: comments,
        FlaggedBy: AppState.currentUser.email,
        FlaggedByName: AppState.currentUser.name,
        Timestamp: new Date().toISOString(),
        StartDate: new Date().toISOString().split('T')[0]
      },
      payload: {
        flag: {
          DocumentID: doc.ID,
          FlagType: flagInfo.type,
          Comments: comments,
          FlaggedBy: AppState.currentUser.email,
          Timestamp: new Date().toISOString()
        }
      }
    }, 'Submitting flag...');

    const data = parseResponse(raw);
    const flagOkVal = data?.ok;
    const flagIsOk = flagOkVal === true || String(flagOkVal).toLowerCase() === 'true' || flagOkVal === undefined;
    if (!flagIsOk) {
      throw new Error(`Flow returned ok: ${flagOkVal} — ${data?.status?.message || 'unknown error'}`);
    }
    const flagRef = data?.data?.referenceId || data?.data?.ReferenceID || data?.data?.taskId || '';
    notifyEl.className = 'notify-banner success show';
    notifyEl.textContent = `✅ ${flagInfo.label} flagged successfully for: ${doc.Title}${flagRef ? ' | Ref: ' + flagRef : ''}`;
    logTelemetry('Flag Action', `${flagInfo.type} on Doc ${doc.ID} — "${doc.Title}"${flagRef ? ' | Ref: ' + flagRef : ''}`, 'Success');
    setTimeout(() => closeFlagModal(), 1800);
  } catch(e) {
    notifyEl.className = 'notify-banner error show';
    notifyEl.textContent = `❌ Failed to submit flag: ${e.message}`;
    submitBtn.disabled = false;
    logTelemetry('Flag Action', `Failed: ${e.message}`, 'Error');
  }
}

async function submitTaskUpdate() {
  const task = AppState.selectedTask;
  if (!task) return;
  const progress = document.getElementById('modal-task-progress').value;
  const priority = document.getElementById('modal-task-priority').value;
  const comments = document.getElementById('modal-task-comments').value.trim();
  const notifyEl = document.getElementById('modal-task-update-notify');
  const submitBtn = document.querySelector('#modal-task-update .modal-footer .btn-primary');
  if (submitBtn) submitBtn.disabled = true;

  notifyEl.className = 'notify-banner info show';
  notifyEl.textContent = '⏳ Submitting update...';

  try {
    // AC6: route through executeSubsidiaryAction dispatcher
    const raw = await executeSubsidiaryAction('updateTask', task.ID, task.Title, {
      operation: 'update',
      mode: 'single',
      TaskUpdate: {
        TaskID: task.ID,
        TaskTitle: task.Title,
        ReferenceID: task.Reference_ID || task.RefIDD || '',
        Progress: progress || task.Progress,
        Priority: priority || task.Priority,
        Comments: comments,
        UpdatedBy: AppState.currentUser.email,
        UpdatedByName: AppState.currentUser.name,
        UpdatedAt: new Date().toISOString(),
        StartDate: new Date().toISOString().split('T')[0]
      },
      payload: {
        task: {
          TaskID: task.ID,
          Progress: progress || task.Progress,
          Priority: priority || task.Priority,
          Comments: comments,
          UpdatedBy: AppState.currentUser.email,
          UpdatedAt: new Date().toISOString()
        }
      }
    }, 'Updating task...');

    const data = parseResponse(raw);
    const updateOkVal = data?.ok;
    const updateIsOk = updateOkVal === true || String(updateOkVal).toLowerCase() === 'true' || updateOkVal === undefined;
    if (!updateIsOk) {
      throw new Error(`Flow returned ok: ${updateOkVal} — ${data?.status?.message || 'unknown error'}`);
    }
    const updateRef = data?.data?.referenceId || data?.data?.ReferenceID || '';
    notifyEl.className = 'notify-banner success show';
    notifyEl.textContent = `✅ Task updated successfully!${updateRef ? ' | Ref: ' + updateRef : ''}`;
    logTelemetry('Task Update', `Task ${task.ID} — Progress: ${progress} | Priority: ${priority}${updateRef ? ' | Ref: ' + updateRef : ''}`, 'Success');
    // Update local state to reflect changes without full refetch
    if (progress) AppState.selectedTask.Progress = progress;
    if (priority) AppState.selectedTask.Priority = priority;
    const taskInList = AppState.tasks.find(t => t.ID === task.ID);
    if (taskInList) {
      if (progress) taskInList.Progress = progress;
      if (priority) taskInList.Priority = priority;
    }
    renderTaskDetail(AppState.selectedTask);
    renderTasksGallery(AppState.tasksFiltered);
    setTimeout(() => closeTaskUpdateModal(), 1500);
  } catch(e) {
    notifyEl.className = 'notify-banner error show';
    notifyEl.textContent = `❌ Update failed: ${e.message}`;
    if (submitBtn) submitBtn.disabled = false;
    logTelemetry('Task Update', `Failed: ${e.message}`, 'Error');
  }
}

