function parseResponse(raw) {
  // Handle double-stringified JSON (Power Automate sometimes returns JSON string)
  let data = raw;
  if (typeof data === 'string') {
    try { data = JSON.parse(data); } catch {}
  }
  // If still string, might be double-stringified (PA flow serialisation artefact)
  if (typeof data === 'string' && data.startsWith('"')) {
    try {
      data = JSON.parse(data);
      // Log a warning so operators can detect and fix PA flow serialisation issues
      logTelemetry('parseResponse', 'Double-stringified JSON detected and unwrapped — check PA flow response serialisation', 'Warning', 0);
    } catch {}
  }
  return data;
}

